\cite{Montgomery19}
\label{thm:RM19}
There exists $C=C(\Delta)$ such that $G(n, \frac{C\log n}{n})$ is a.a.s $\mathcal{T}(n, \Delta)$-universal.

\cite{Alon07}
Is it true that for every $\Delta\in \mathbb{N}$, there exists $c=c(\Delta)>0$ such that every
$(n, d,\lambda)$-graph with $\frac{\lambda}{d}<c$ is $\mathcal{T}(n, \Delta)$-universal?

\cite{Alon07,BCPS10}
For all $\Delta\in \mathbb{N}$ and constant $0<\varepsilon<1/2$, every
$(n, d,\lambda)$-graph with \[\frac{\lambda}{d}\le\frac{\varepsilon}{\sqrt{8\Delta}}\] is $\mathcal{T}(n-\varepsilon n, \Delta)$-universal.

\cite{JKS12}\label{expander}
Given $n \in\mathbb{N}$ and $d>0$, an $n$-vertex graph $G$ is an $(n, d)$-\emph{expander}
if $G$ satisfies the following two conditions:
\begin{enumerate}[label=(\roman*)]
  \item $|N_G(X)| \ge d|X|$ for all $X \subseteq V(G)$ with $1 \le |X| < \frac{n}{2d}$;
  \item $e_G(X, Y) > 0$ for all disjoint $X, Y \subseteq V(G)$ with $|X| = |Y | \ge\frac{n}{2d}$.
\end{enumerate}

\label{expands}
For a graph $G$ and a set $W\< V(G)$, we say $G$ \emph{$d$-expands} into $W$ if
\begin{enumerate}[label=(\roman*)]
\item $|N_G(X, W)|\geq d|X|$ for all $X\<V(G)$ with $1\leq |X|<\lceil \frac{|W|}{2d}\rceil$, and,
\item $e_G(X,Y)>0$ for all disjoint $X,Y\<V(G)$ with $|X|=|Y|=\lceil\frac{|W|}{2d}\rceil$.
\end{enumerate}

\label{th1+}
There exists $n_0\in \mathbb{N}$ such that for all integers $n,\Delta$ with $n\ge n_0$ and $\Delta\ge 2$, every
$(n, d)$-expander with \[d\ge\Delta^{5\sqrt{\log n}}\] is $\mathcal{T}(n, \Delta)$-universal.

\cite{JKS12}
There exists an absolute constant $C>0$ such that the following statement
holds. Let $n,\Delta,b\in\mathbb{N}$ satisfy $\Delta \ge \log n$. Then the $(1 : b)$ Maker-Breaker $\mathcal{T}(n,\Delta)$-universality game is Maker's win on every $(n, d)$-expander with $d \ge Cb\Delta n^{
2/3}\log n$.

\cite{Kri10}
\label{lem:fact}
For any integers $n, k > 2$, an $n$-vertex tree either has at least $\frac{n}{4k}$
leaves or a collection of at least $\frac{n}{4k}$ vertex disjoint bare paths each of length $k$.

\label{newdiv}
For any integers $n, \Delta, k > 2$, an $n$-vertex tree $T\in \mathcal{T}(n,\Delta)$ either has at least $\frac{n}{4k\Delta}$
pendant stars or a collection of at least $\frac{n}{4k\Delta}$ vertex disjoint caterpillars each of length $k$.

\cite[Lemma~3.10]{JKS12}\label{star}
Let $d, m\in \mathbb{N}$ and $G$ be a graph. Suppose that two disjoint
sets $A, B \subseteq V(G)$ satisfy the following conditions:
\begin{enumerate}
  \item [$(1)$] $|N_G(X)\cap B| \ge d|X|$ for all $X \subseteq A$ with $1\le |X| \le m$;
  \item [$(2)$] $e_G(X, Y) > 0$ for all $X\subseteq A, Y\subseteq B$ with $|X| = |Y |=m$.
  \item [$(3)$] $|N_G(w) \cap A| \ge m$ for all $w \in B$.
\end{enumerate}
Then, for every $f: A\rightarrow \{1, \ldots, d\}$ with $\sum_{u\in A}f(u) = |B|$, there exists an $f$-matching from $A$ into $B$.

\label{star1}
Let $d,m\in \mathbb{N}$ and $G$ be a graph. Suppose that two disjoint
sets $A, B \subseteq V(G)$ satisfy that
\begin{enumerate}
  \item [$(1)$] $|N_G(X)\cap B| \ge d|X|, N_G(Y)\cap A| \ge d|Y|$ for all $X \subseteq A, Y\<B$ with $1\le |X|,|Y| \le m$;
  \item [$(2)$]\label{equ1} $e_G(X, Y) > 0$ for all $X\subseteq A, Y\subseteq B$ with $|X| = |Y |=m$
\end{enumerate}
Then, for every $f: A\rightarrow \{1, \ldots, d\}$ with $\sum_{u\in A}f(u) = |B|$, there exists an $f$-matching from $A$ into $B$.

To build a desired star-matching, we shall show a generalized Hall's condition (see, e.g., Bollob\'{a}s \cite{Bo98})), that is,
\begin{eqnarray}\label{eq4}
|N(X)\cap B|\ge \sum_{v\in X}f(v)~\text{for every}~X\<A.
\end{eqnarray}
From the assumption that every set $X$ of at most $m$ vertices in $A$ has at least $d|X|$ neighbors in $B$, we know that \eqref{eq4} holds when $|X|\le m$. It remains to consider the following two cases depending on the size of $|X|$:
\begin{itemize}
  \item $m<|X|\le |A|-m$: By the assumption~$(2)$ and $|B|=\sum_{v\in A}f(v)$, we have \[|N(X)\cap B|> |B|-m\ge \sum_{v\in A}f(v)-\sum_{v\in A\setminus X}f(v)=\sum_{v\in X}f(v),\] where the second inequality follows as $m\le |A|-|X|\le\sum_{v\in A\setminus X}f(v)$.
  \item $|A|-m<|X|\le |A|$: Let $T:=B\setminus N(X)$. We may assume that $T\neq\emptyset$ for otherwise we are done. As there is no edge between $X$ and $T$, we obtain that $|T|<m$ and $N(T)\cap A\<A\setminus X$. Then it follows by assumption that $d |T|\le|N(T)\cap A|\le|A\setminus X|\le\sum_{v\in A\setminus X}f(v)$. Thus we have
      \[|N(X)\cap B|=|B|-|T|=\sum_{v\in X}f(v)+\sum_{v\in A\setminus X}f(v)-|T|>\sum_{v\in X}f(v).\]
\end{itemize}
In all cases, condition~\eqref{eq4} holds and this yields a desired star-matching covering $A\cup B$.

\cite{Montgomery14}
\label{pathcover}
Let $n$ be sufficiently large and let $\ell\in \mathbb{N}$ satisfy $\ell\geq 10^3\log^2n$ and $\ell|n$. Let a graph $G$ contain $n/\ell$ disjoint vertex pairs $(x_i,y_i)$ and let $W=V(G)\setminus (\cup_i\{x_i,y_i\})$. Suppose $G$ $d$-expands into $W$, where $d=10^{10}\log^4 n/\log\log n$. Then we can cover $G$ with $n/\ell$ disjoint paths $P_i$, each of length $\ell-1$, so that, for each $i$,  $P_i$ is an $(x_i,y_i)$-path.

\label{pathcover2}
There exists $C>0$ such that the following holds for any integer $\ell\ge 200$ and sufficiently integer $n$ with $\ell|n$. Suppose an $n$-vertex graph $G$ contains $n/\ell$ disjoint vertex pairs $(x_i,y_i),i\in[n/\ell]$ and let $W=V(G)\setminus (\cup_i\{x_i,y_i\})$. If $G$ $d$-expands into $W$                                         
 with $d=C\ell\sqrt{n}$, then we can cover $G$ with $n/\ell$ disjoint paths $P_i$, each of length $\ell-1$, so that, for each $i$,  $P_i$ is an $(x_i,y_i)$-path.

\label{def:tree}
Given a graph $G$, a subset of vertices $W$, a collection $\mathcal{I}$ of disjoint pairs of vertices from $V(G)\setminus W$ and integers $s,\Delta$, we call that $G$ contains a $(W,\mathcal{I},s,\Delta)$\emph{-tree array} if there exist
\begin{itemize}
	\item a family $\mathcal{P}=\{P_{xy}: (x,y)\in \mathcal{I}\}$ of mutually vertex-disjoint paths each of length $s$, where the internal vertices of all paths $P_{xy}$, denoted as $\mathsf{Int}(\mathcal{P})$, lie inside $W$;
	\item a family $\{T_v\}_{v\in \mathsf{Int}(\mathcal{P})}$ of mutually vertex-disjoint rooted trees inside $W$, such that for every path $P_{xy}$ and every internal vertex $v$, $T_v$ is a $\Delta$-ary tree rooted at $v$ with height $s$, which is vertex disjoint from $V(\mathcal{P})\setminus\{v\}$.                                                                                                                                                                                                                                                                                                           
    \end{itemize}

\label{pendant}
For any constant $0<\gamma<\frac{1}{2}$, there exists $c>0$ such that the following holds for sufficiently large integer $n$. For all $\Delta\in \mathbb{N}$ with $\Delta \le c\sqrt{n}$, every
$(n, \frac{100}{\gamma}\Delta \sqrt{n})$-expander is universal for the trees in $\mathcal{T}(n, \Delta)$ with  at least $\frac{\gamma n}{\Delta}$ pendant stars.

\label{caterpillar}
For any integer $k\ge 800$ there exists $C>0$ such that the following holds for sufficiently large integer $n$. For all $\Delta\in \mathbb{N}$ with $\Delta \le\frac{\sqrt{n}}{2C}$, every
$(n, C\Delta \sqrt{n})$-expander is universal for the trees in $\mathcal{T}(n, \Delta)$ with at least $\frac{ n}{4k\Delta}$ vertex-disjoint caterpillars each of length $k$.

\cite[Corollary 6]{han}\label{almost2}
Let $\Delta,m,M\in \mathbb{N}$ and $H$ be a non-empty graph such that for every $X\<V(H)$, if $0<|X|\leq m$, then $N_H(X)|\geq \Delta|X|+1$ and, if $|X|=m$, then $|N_H(X)|\geq \Delta m+M$, then $H$ contains every tree in $\mathcal{T}(M,\Delta)$. Moreover, for any $T\in \mathcal{T}(M,\Delta)$ and any vertices $x\in V(T),y\in V (G)$, there exists
an embedding of $T$ into $G$ which maps $x$ to $y$.
